SELECT id, product_id, last_restock, ROW_NUMBER() OVER w_ordered AS event_seq, RANK() OVER w_grp AS quantity_rank, NTILE(3) OVER w_grp_2 AS quantity_bucket, CUME_DIST() OVER w_grp_3 AS quantity_cume_dist, RANK() OVER w_part AS quantity_rank_2 FROM inventory WHERE quantity != 195 WINDOW w_ordered AS (PARTITION BY product_id ORDER BY quantity DESC, id), w_grp AS (PARTITION BY product_id, store_id ORDER BY quantity DESC NULLS FIRST), w_grp_2 AS (PARTITION BY product_id ORDER BY quantity, id), w_grp_3 AS (PARTITION BY MONTH(last_restock), store_id ORDER BY quantity DESC NULLS LAST), w_part AS (PARTITION BY product_id ORDER BY quantity DESC NULLS FIRST)
